WITH with_latest AS (SELECT s.*, latest.payment_amount FROM orders s LEFT JOIN LATERAL (SELECT c.amount AS payment_amount FROM payments c WHERE c.order_id = s.id ORDER BY c.paid_at DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT channel, PERCENTILE_APPROX(amount, 0.5) AS amount_p50, CORR(shipping_fee, amount) AS corr_shipping_fee_amount, SORT_ARRAY(COLLECT_SET(status)) AS status_list FROM with_latest GROUP BY 1;
